from __future__ import annotations

from marshmallow import EXCLUDE, Schema, ValidationError, fields, validates_schema
from marshmallow.validate import OneOf


class _SignupSchema(Schema):
    class Meta:
        unknown = EXCLUDE  # drop unknown keys

    username = fields.String(required=True)
    email = fields.Email(required=True)

    plan = fields.String(
        missing="free",
        validate=OneOf(["free", "pro", "team"], error="Must be one of: free, pro, team."),
    )

    age = fields.Integer(required=False)

    @fields.validates("username")
    def _validate_username(self, value: str) -> None:
        if not value.isalnum():
            raise ValidationError("Username must be alphanumeric.")

    @validates_schema
    def _validate_age(self, data, **kwargs) -> None:
        # Only validate when present (optional field).
        if "age" in data and data["age"] is not None:
            if not (16 <= int(data["age"]) <= 120):
                raise ValidationError({"age": ["Age must be between 16 and 120."]})


class SignupValidationError(ValueError):
    def __init__(self, messages: dict[str, list[str]]):
        super().__init__("invalid signup data")
        self.messages = messages


def validate_signup(data: dict) -> dict:
    """
    Validate and clean signup payload.

    Required: username (alphanumeric), email (valid email)
    Optional: plan (default 'free', one of 'free'|'pro'|'team'), age (16..120)
    Unknown keys are dropped.

    Returns cleaned dict; raises ValueError with .messages on invalid input.
    """
    schema = _SignupSchema()
    try:
        return schema.load(data)
    except ValidationError as err:
        # marshmallow gives messages as dict[str, list[str] | nested], normalize to dict[str, list[str]]
        messages = {}
        for field, field_messages in err.messages.items():
            if isinstance(field_messages, list):
                messages[field] = [str(m) for m in field_messages]
            else:
                # In case of unexpected structure, stringify.
                messages[field] = [str(field_messages)]
        raise SignupValidationError(messages) from None

from __future__ import annotations

from urllib.parse import parse_qsl, urlencode

import httpx

from api_fetch import ApiError, RETRY_STATUSES


def _get_json_with_retries(client: httpx.Client, path: str, *, retries: int) -> dict:
    last_exc: Exception | None = None
    for attempt in range(retries + 1):
        response = client.get(path)
        if response.status_code in RETRY_STATUSES and attempt < retries:
            continue
        if response.is_error:
            raise ApiError(response.status_code, response.text)
        return response.json()
    # Should not be reachable, but keep mypy/humans happy.
    raise last_exc or ApiError(500, "request failed")


def _merge_query_into_relative_url(relative_url: str, *, extra: dict[str, str]) -> str:
    """
    httpx==0.28 no longer merges `params=` with an existing query string.
    The server returns `next` as a relative URL carrying cursor in its query.
    We preserve that query and overwrite/insert required params.
    """
    if "?" not in relative_url:
        return relative_url + "?" + urlencode(extra)

    base, _, query = relative_url.partition("?")
    current = dict(parse_qsl(query, keep_blank_values=True))
    current.update(extra)
    return base + "?" + urlencode(current, doseq=True)


def open_ticket_titles(client: httpx.Client, project: str) -> list[str]:
    """
    GET /tickets with status=open and project=<project>.
    Follows `next` pages (relative URL containing cursor in query string).
    Returns all ticket titles in order.
    """
    titles: list[str] = []
    retries = 2

    url: str | None = "/tickets"
    while url:
        url = _merge_query_into_relative_url(
            url,
            extra={
                "status": "open",
                "project": project,
            },
        )
        data = _get_json_with_retries(client, url, retries=retries)
        items = data.get("items", [])
        for item in items:
            if "title" in item:
                titles.append(item["title"])
            else:
                titles.append(None)  # type: ignore[list-item]  # defensive; expected by schema
        next_url = data.get("next")
        url = next_url if next_url else None

    # Titles are expected to be strings by the API contract.
    return [t for t in titles if t is not None]

