    def _validate_username(self, value: str) -> None:
        if not value.isalnum():
            raise ValidationError("Username must be alphanumeric.")

    @validates("plan")
    def _validate_plan(self, value: str) -> None:
        allowed = {"free", "pro", "team"}
        if value not in allowed:
            raise ValidationError(f"Plan must be one of: {', '.join(sorted(allowed))}.")

    @validates("age")
    def _validate_age(self, value: int) -> None:
        if value is None:
            return
        if not (16 <= value <= 120):
            raise ValidationError("Age must be between 16 and 120 inclusive.")


def validate_signup(data: dict) -> dict:
    """
    Validate and clean sign-up payload.

    Required fields:
      - username: alphanumeric string
      - email: valid email address

    Optional fields:
      - plan: defaults to "free", must be one of {"free","pro","team"}
      - age: integer between 16 and 120 inclusive

    Unknown keys are dropped.

    Returns cleaned dict. On invalid input raises ValueError with a .messages
    attribute mapping field name -> list of error messages.
    """
    try:
        return _SignupSchema().load(data)
    except ValidationError as err:
        messages = err.messages if isinstance(err.messages, dict) else {"_schema": err.messages}
        exc = ValueError("invalid signup data: %s" % (messages,))
        exc.messages = messages
        raise exc

from __future__ import annotations

from importlib import metadata
from typing import Optional


def dependency_report(names: list[str]) -> dict[str, str | None]:
    """
    Map each provided distribution name (exactly as given) to its installed
    version string, or None if not installed.

    Matching is case-insensitive.
    """
    result: dict[str, str | None] = {}

    # Build a case-insensitive lookup once for efficiency.
    try:
        dists = metadata.distributions()
    except Exception:
        dists = []

    version_by_lower: dict[str, str] = {}
    for dist in dists:
        name = getattr(dist, "metadata", None)
        dist_name = None
        if name is not None:
            # Using email.message.Message interface: .get('Name')
            try:
                dist_name = name.get("Name")
            except Exception:
                dist_name = None
        if not dist_name:
            # Fallback for older/edge distributions
            dist_name = getattr(dist, "name", None)

        if dist_name:
            try:
                version_by_lower[dist_name.lower()] = dist.version
            except Exception:
                # If a distribution lacks version info, treat as absent for reporting.
                pass

    for original in names:
        key = original.lower()
        result[original] = version_by_lower.get(key)

    return result

